    $practice=function($raw,$directions){ list($question,$answer)=array_map('trim',explode('|',$raw,2)); return $directions.' || '.$question.' | '.$answer.' | Build or sketch the place-value model before calculating. | Work one place at a time and label every regrouping or comparison. | Use the lesson model, calculate carefully, and estimate or use the inverse operation to check.'; };
